"""Summarize workflow tables without changing the node."""
import argparse
from datetime import datetime, timedelta, timezone
import json
from pathlib import Path
import re


REQUIRED = {
    "routines": ("name", "every", "last_time", "last_code"),
    "schedule": ("name", "at", "claimed"),
}
SECONDS = {"s": 1, "m": 60, "h": 3600, "d": 86400}


def nonfinite(value):
    raise ValueError("non-finite JSON number")


def problem(table, row, why):
    return {"table": table, "row": row, "why": why}


def read_table(node, table):
    try:
        with (node / "wf" / (table + ".json")).open(encoding="utf-8") as stream:
            value = json.load(stream, parse_constant=nonfinite)
    except FileNotFoundError:
        return [], []
    except (OSError, UnicodeError, ValueError):
        return [], [problem(table, None, "bad_table")]
    if (not isinstance(value, dict) or value.get("contract") != "wf-table/1"
            or not isinstance(value.get("columns"), list)
            or not all(isinstance(column, str) for column in value["columns"])
            or not isinstance(value.get("rows"), list)):
        return [], [problem(table, None, "bad_table")]
    return value["rows"], []


def timestamp(text, zone):
    value = datetime.fromisoformat(text)
    return value.replace(tzinfo=zone) if value.tzinfo is None else value


def summarize(node, now):
    routines, schedule, bad = [], [], []
    for table in ("routines", "schedule"):
        rows, errors = read_table(node, table)
        bad.extend(errors)
        seen = set()
        for index, row in enumerate(rows):
            name = row.get("name") if isinstance(row, dict) else None
            if isinstance(name, str) and name:
                if name in seen:
                    bad.append(problem(table, index, "dup_name"))
                    continue
                seen.add(name)
            if (not isinstance(row, dict)
                    or any(not isinstance(value, str) for value in row.values())
                    or any(key not in row for key in REQUIRED[table])
                    or not isinstance(name, str) or not name):
                bad.append(problem(table, index, "bad_row"))
                continue
            try:
                if table == "routines":
                    every, last, code = row["every"], row["last_time"], row["last_code"]
                    if re.fullmatch(r"[1-9][0-9]*[rsmhd]", every) is None:
                        raise ValueError("invalid interval")
                    last_dt = timestamp(last, now.tzinfo) if last else None
                    if code == "running":
                        last_code = "running"
                    elif code == "":
                        last_code = None
                    elif re.fullmatch(r"[+-]?[0-9]+", code):
                        last_code = int(code)
                    else:
                        raise ValueError("invalid exit code")
                    next_dt = None
                    if last_dt is not None and every[-1] != "r":
                        next_dt = last_dt + timedelta(
                            seconds=int(every[:-1]) * SECONDS[every[-1]])
                    next_text = (next_dt.astimezone(timezone.utc).isoformat(
                        timespec="seconds").replace("+00:00", "Z")
                        if next_dt is not None else None)
                    if last_code == "running":
                        state = "running"
                    elif last_dt is None:
                        state = "never"
                    elif isinstance(last_code, int) and last_code != 0:
                        state = "failed"
                    elif next_dt is not None and now >= next_dt:
                        state = "overdue"
                    else:
                        state = "ok"
                    routines.append({"name": name, "every": every,
                                     "last_time": last or None, "last_code": last_code,
                                     "state": state, "next": next_text})
                else:
                    at = row["at"]
                    when = timestamp(at, now.tzinfo)
                    state = ("interrupted" if row["claimed"] else
                             "due" if when <= now else "pending")
                    schedule.append({"name": name, "at": at, "state": state})
            except (ValueError, OverflowError):
                bad.append(problem(table, index, "bad_row"))
    routines.sort(key=lambda row: row["name"])
    schedule.sort(key=lambda row: row["name"])
    bad.sort(key=lambda item: (item["table"],
                               -1 if item["row"] is None else item["row"], item["why"]))
    return {
        "v": 1, "routines": routines, "schedule": schedule,
        "counts": {
            "routines": {state: sum(row["state"] == state for row in routines)
                         for state in ("running", "never", "failed", "overdue", "ok")},
            "schedule": {state: sum(row["state"] == state for row in schedule)
                         for state in ("interrupted", "due", "pending")},
        },
        "bad": bad,
    }


def main(argv=None):
    parser = argparse.ArgumentParser(description="Read-only workflow summary")
    parser.add_argument("folder", type=Path)
    parser.add_argument("--now", required=True)
    args = parser.parse_args(argv)
    try:
        now = datetime.fromisoformat(args.now)
    except ValueError:
        parser.error("--now must be an ISO timestamp with a timezone")
    if now.tzinfo is None:
        parser.error("--now must have a timezone")
    if not args.folder.is_dir():
        parser.error("folder must be a directory")
    print(json.dumps(summarize(args.folder, now), separators=(",", ":")))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
